public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return result;
    }
    backtrace(nums, 0, new ArrayList<>(), result);
    return result;
}

private void backtrace(int[] nums, int start, List<Integer> path, List<List<Integer>> result) {
    if (path.size() == nums.length) {
        result.add(new ArrayList<>(path));
        return;
    }
    for (int i = start; i < nums.length; i++) {
        if (isUsed(nums, start, i)) {
            continue;
        }
        path.add(nums[i]);
        backtrace(nums, i + 1, path, result);
        path.remove(path.size() - 1);
    }
}

private boolean isUsed(int[] nums, int start, int end) {
    for (int i = start; i < start + end; i++) {
        if (nums[i] == nums[end]) {
            return true;
        }
    }
    return false;
}

public List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        if (nums == null || nums.length == 0) {
            return result;
        }
        helper(nums, 0, result);
        return result;
    }

private void helper(int[] nums, int start, List<List<Integer>> result) {
        if (start == nums.length) {
            result.add(new ArrayList<>(Arrays.asList(nums))); // Without the sublist copy, the list of lists will accumulate changes
            return;
        }
        for (int i = start; i < nums.length; i++) {
            swap(nums, start, i);
            helper(nums, start + 1, result);
            swap(nums, start, i); // Backtrack
        }
    }

private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }

