public static int countOilDeposits(char[][] grid) {
    int count = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                if (!isPorousTile(grid, i, j)) {
                    count++;
                }
            }
        }
    }
    return count;
}

private static boolean isPorousTile(char[][] grid, int x, int y) {
    if (x == 0 || y == 0 || x == grid.length - 1 || y == grid[x].length - 1) {
        return false; // Touching the edges
    }
    for (int i = Math.max(0, x - 1); i <= Math.min(grid.length - 1, x + 1); i++) {
        for (int j = Math.max(0, y - 1); j <= Math.min(grid[i].length - 1, y + 1); j++) {
            if (grid[i][j] == '*') {
                return true; // Found an oil pocket
            }
        }
    }
    return false; // No oil pocket found in the current grid square
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        throw new IllegalArgumentException("'grid' should be a non-empty 2D array.");
    }

    int[][] visited = new int[grid.length][grid[0].length];
    int count = 0;

    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            if (grid[i][j] == '*' || visited[i][j] == 1) {
                continue; // Skip visited or oil-free cells.
            }
            dfs(grid, i, j, visited);
            count++;
        }
    }

    return count;
}

private static void dfs(char[][] grid, int row, int col, int[][] visited) {
    if (row < 0 || row >= grid.length || col < 0 || col >= grid[0].length || grid[row][col] == '*' || visited[row][col] == 1) {
        return;
    }
    visited[row][col] = 1; // Mark cell as visited.
    dfs(grid, row - 1, col, visited); // Top
    dfs(grid, row + 1, col, visited); // Bottom
    dfs(grid, row, col - 1, visited); // Left
    dfs(grid, row, col + 1, visited); // Right
}

