private static void markAsVisited(char[][] grid, int i, int j) {
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || grid[i][j] != '@') {
        return;
    }
    grid[i][j] = '#'; // Mark the oil spot as visited
    markAsVisited(grid, i - 1, j); // Explore north
    markAsVisited(grid, i + 1, j); // Explore south
    markAsVisited(grid, i, j - 1); // Explore west
    markAsVisited(grid, i, j + 1); // Explore east
}

