}

private static void dfs(char[][] grid, boolean[][] visited, int x, int y) {
    if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length || grid[x][y] == '*' || visited[x][y]) {
        return;
    }
    visited[x][y] = true;
    // Process current oil pocket (e.g., increment count)
    // Here, we assume a simple counting mechanism
    // In a real scenario, the processing logic would depend on the abuse tier requirements
    // For the sake of this example, we just increment the count
    grid[x][y];
    dfs(grid, visited, x + 1, y);
    dfs(grid, visited, x - 1, y);
    dfs(grid, visited, x, y + 1);
    dfs(grid, visited, x, y - 1);
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }

    int rows = grid.length;
    int cols = grid[0].length;
    int deposits = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@') {
                dfs(grid, i, j);
                deposits++;
            }
        }
    }

    return deposits;
}

private void dfs(char[][] grid, int x, int y) {
    if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length || grid[x][y] == '*') {
        return;
    }
    grid[x][y] = '*'; // Mark the cell as visited

    dfs(grid, x + 1, y);
    dfs(grid, x - 1, y);
    dfs(grid, x, y + 1);
    dfs(grid, x, y - 1);
}

