        return "cannot be travelled";
    }
    boolean[][] visited = new boolean[n][n];
    visited[start[0]][start[1]] = true;
    return dfs(start[0], start[1], end[0], end[1], paths, visited);
}

private static String dfs(int x, int y, int targetX, int targetY, int[][] paths, boolean[][] visited) {
    if (x == targetX && y == targetY) {
        return "can be travelled";
    }
    for (int[] path : paths) {
        int newX = x + path[0];
        int newY = y + path[1];
        if (newX >= 0 && newX < visited.length && newY >= 0 && newY < visited[0].length &&
            !visited[newX][newY] && paths[newX][newY] == 1) {
            visited[newX][newY] = true;
            String result = dfs(newX, newY, targetX, targetY, paths, visited);
            if (result != null) {
                return result;
            }
            visited[newX][newY] = false;
        }
    }
    return "cannot be travelled";
}

