    return visited.contains(endToString(end)) ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int n, int[] start, int[] end, int[][] paths, HashSet<String> visited, boolean[] visitedArray) {
    visited.add(startToString(start));
    visitedArray[start[0] * n + start[1]] = true;
    int x = start[0], y = start[1];
    if (x == end[0] && y == end[1]) return true;
    for (int[] path : paths) {
        int newX = x + path[0], newY = y + path[1];
        if (newX >= 0 && newX < n && newY >= 0 && newY < n && !visitedArray[newX * n + newY] && !visited.contains(endToString(new int[]{newX, newY}))) {
            if (dfs(n, new int[]{newX, newY}, end, paths, visited, visitedArray)) return true;
        }
    }
    return false;
}

private static String startToString(int[] start) {
    return start[0] + "_" + start[1];
}

private static String endToString(int[] end) {
    return end[0] + "_" + end[1];
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create a map to store the adjacency list representation of the maze
    Map<String, Map<String, Boolean>> maze = new HashMap<>();

    // Initialize the cave map with all its entries as false
    for (int i = 0; i <= n; i++) {
        maze.put("" + i, new HashMap<>());
    }

    // Populate the cave map with path data
    for (int[] path : paths) {
        maze.get("" + path[0]).put("" + path[1], true);
        maze.get("" + path[1]).put("" + path[0], true);
    }

    // Convert coordinates to string format for Map key
    String startString = "" + start[0] + "," + start[1];
    String endString = "" + end[0] + "," + end[1];

    // Initialize a queue for BFS
    Queue<String> queue = new LinkedList<>();
    queue.add(startString);
    boolean[] visited = new boolean[n * n + 2]; // Add extra空间 to handle the start and end points

    // Start BFS from the start point
    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(endString)) {
            return "can be travelled";
        }
        int[] position = parsePosition(current);
        visited[position[0] * n + position[1]] = true;

        // Explore all adjacent positions
        for (Map.Entry<String, Boolean> neighbor : maze.get(current).entrySet()) {
            String next = neighbor.getKey();
            if (!visited[next.charAt(0) * n + next.charAt(1)]) {
                queue.add(next);
            }
        }
    }

    return "cannot be travelled";
}

private static int[] parsePosition(String positionString) {
    String[] parts = positionString.split(",");
    return new int[]{Integer.parseInt(parts[0]), Integer.parseInt(parts[1])};
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the source and destination coordinates are within the valid range
    if (start[0] < 0 || start[1] < 0 || start[0] >= n || start[1] >= n ||
        end[0] < 0 || end[1] < 0 || end[0] >= n || end[1] >= n) {
        return "cannot be travelled";
    }

    int[] directions[] = {
        {1, 0}, // right
        {0, 1}, // down
        {-1, 0}, // left
        {0, -1} // up
    };

    boolean[][] visited = new boolean[n][n];
    boolean found = false;

    // Perform DFS to check if a path exists
    for (int[] dir : directions) {
        int x = start[0] + dir[0];
        int y = start[1] + dir[1];
        if (x >= 0 && x < n && y >= 0 && y < n && !visited[x][y] && paths[x][y] == 1) {
            visited[x][y] = true;
            dfs(x, y, end, paths, visited);
            if (found) {
                return "can be travelled";
            }
        }
    }

    if (!found) {
        return "cannot be travelled";
    }
}

public static String appx(String word1, String word2) {
    // Validate input
    if (word1 == null || word2 == null || word1.isEmpty() || word2.isEmpty()) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Count common letters
    int commonLetters = 0;
    for (char c : word1.toCharArray()) {
        if (word2.indexOf(c) >= 0) {
            commonLetters++;
        }
    }

    // Calculate the approximate value
    BigInteger gcd = BigInteger.valueOf(commonLetters).gcd(BigInteger.valueOf(word1.length() + word2.length()));
    commonLetters /= gcd.intValue();
    BigInteger denominators = BigInteger.valueOf(word1.length() + word2.length()).divide(gcd);

    return "appx(" + word1 + ", " + word2 + ") = " + commonLetters + "/" + denominators.toString();
}

public static String appx(String word1, String word2) {
    int commonCount = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonCount++;
                break;
            }
        }
    }

    long gcd = calculateGCD(commonCount, word1.length() + word2.length());
    commonCount /= gcd;
    int denominator = word1.length() + word2.length() / gcd;

    return "appx(" + word1 + ", " + word2 + ") = " + commonCount + "/" + denominator;
}

private static int calculateGCD(int a, int b) {
    if (b == 0) return a;
    return calculateGCD(b, a % b);
}

public static String appx(String word1, String word2) {
        if (word1 == null || word2 == null || word1.isEmpty() || word2.isEmpty()) {
            throw new IllegalArgumentException("Input words cannot be null or empty");
        }

        int commonLetters = 0;
        int totalLetters = word1.length() + word2.length();

        for (char c : word1.toCharArray()) {
            if (word2.indexOf(c) != -1) {
                commonLetters++;
            }
        }

        double fraction = (double) commonLetters / totalLetters;
        return String.format("appx(%s, %s) = %d/%d", word1, word2, (int) Integer.signum(fraction), (int) Long.toUnsignedLong(fraction));
    }

public static String appx(String word1, String word2) {
    int commonLetters = 0;
    for (int i = 0; i < word1.length() && i < word2.length(); i++) {
        if (word1.charAt(i) == word2.charAt(i)) {
            commonLetters++;
        }
    }
    int numerator = commonLetters;
    int denominator = word1.length() + word2.length() - commonLetters;
    if (denominator == 0) {
        throw new IllegalArgumentException(" Negative length for approximate value calculation");
    }
    return "appx(" + word1 + ", " + word2 + ") = " + toReducedFraction(numerator, denominator);
}

private static String toReducedFraction(int numerator, int denominator) {
    BigInteger num = BigInteger.valueOf(numerator);
    BigInteger den = BigInteger.valueOf(denominator);
    final BigInteger gcd = num.gcd(den);
    while (gcd.compareTo(BigInteger.ONE) != 0) {
        num = num.divide(gcd);
        den = den.divide(gcd);
        gcd = num.gcd(den);
    }
    return Math.abs(numerator) == Math.abs(denominator) ? "1" : num.toString() + "/" + den.toString();
}

public static String appx(String word1, String word2) {
    BigInteger commonLetters = word1.chars().filter(c -> word2.indexOf(c) != -1).count();
    BigInteger sumOfLengths = new BigInteger(word1.length() + word2.length());
    BigInteger reducedFraction = commonLetters.divide(sumOfLengths);
    return "appx(" + word1 + ", " + word2 + ") = " + reducedFraction.toString();
}

