public double trimMean(int[] arr) {
    Arrays.sort(arr);
    int removeCnt = arr.length * 0.05;
    double totalSum = 0;
    for (int i = removeCnt; i < arr.length - removeCnt; i++) {
        totalSum += arr[i];
    }
    double mean = totalSum / (arr.length - 2 * removeCnt);
    return mean;
}

