    Arrays.sort(arr);
    var size = arr.length;
    var trimmedSize = size * 0.95;
    var sum = Arrays.stream(arr).skip((int) (trimmedSize)).limit((int) (trimmedSize)).sum();
    return sum / trimmedSize;
}

