        }

        Arrays.sort(arr);
        int size = arr.length;
        int numToRemove = size / 20;  // Remove 5% of elements from both ends

        // Calculate the sum of the remaining elements
        double sum = 0.0;
        for (int i = numToRemove; i < size - numToRemove; i++) {
            sum += arr[i];
        }

        // Calculate the mean
