public double trimMean(int[] arr) {
    Arrays.sort(arr);
    int size = arr.length;
    double trimmedSum = 0;

    // Calculate the smallest 5% and largest 5% indices
    int startIndex = size * 5 / 100;
    int endIndex = size - 1 - startIndex;

    // Sum up the elements from the middle
    for (int i = startIndex + 1; i < endIndex; i++) {
        trimmedSum += arr[i];
    }

    // Calculate the mean within the trimmed range
    double mean = trimmedSum / (endIndex - startIndex - 1);
    return mean;
}

