    double sum = 0;
    for (int i = low; i < n - high; i++) {
        sum += arr[i];
    }

    return sum / (n - 2 * high);
}

public boolean canArrange(int[] arr, int k) {
    int[] count = new int[k];
    for (int num : arr) {
        if (num % k == 0) {
            count[0]++;
        } else {
            count[num % k]++;
        }
    }
    if (k % 2 == 0) {
        return count[0] % 2 == 0;
    } else {
        return count[0] == count[k - 1];
    }
}

public boolean canArrange(int[] arr, int k) {
        // Check if the length of the array is odd
        if (arr.length % 2 != 0) {
            return false;
        }

        // Count the occurrences of each remainder when divided by k
        int[] count = new int[k];
        for (int num : arr) {
            count[num % k]++;
        }

        // Initialize a count for numbers with remainder 0
        int remainder0 = 0;

        // Iterate through the count array
        for (int i = 1; i < k; i++) {
            if (remainder0 > count[i]) {
                // Ensure there is at least one number with remainder 0 and an odd count
                if (count[0] == 0 || count[remainder0] % 2 == 0) {
                    return false;
                }
                // Update remainder0 by subtracting count[i] from the sum of all remainders
                remainder0 += count[i];
                count[i] = 0;
            } else if (remainder0 != count[i]) {
                // Ensure either count[0] is even or count[i] is even
                if ((remainder0 % 2 == 0 && count[0] % 2 != 0) || (remainder0 % 2 != 0 && count[i] % 2 != 0)) {
                    return false;
                }
                // Update the count of the remainder
                count[i] -= remainder0;
                count[0] = remainder0;
                remainder0 = 0;
            }
        }

        // Check if count[0] is even
        return count[0] % 2 == 0;
    }

public static boolean canArrange(int[] arr, int k) {
        if (arr == null || arr.length % 2 != 0) {
            throw new IllegalArgumentException("Input array must be non-empty and have an even length.");
        }

        Arrays.sort(arr);
        for (int i = 0; i < arr.length / 2; i++) {
            String pairSum = arr[i] + arr[arr.length - i - 1];
            if (!checkDivisibility(pairSum, k)) {
                return false;
            }
        }
        return true;
    }

private static boolean checkDivisibility(String num, int divisor) {
        int remainder = Integer.parseInt(num) % divisor;
        return remainder == 0;
    }

public boolean canArrange(int[] arr, int k) {
    // Check if the array can be divided into n/2 pairs
    if (arr.length % 2 != 0) {
        return false;
    }

    Map<Integer, Integer> remainders = new HashMap<>();
    for (int num : arr) {
        int remainder = num % k;
        if (remainder == 0 || (k - remainder) % 2 == 0) {
            remainders.put(remainder, remainders.getOrDefault(remainder, 0) + 1);
        } else {
            // If the remainder is 1 or k-1, there must be an odd number of occurrences
            if (remainders.get(remainder) % 2 != 0) {
                return false;
            }
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
        int[] counts = new int[k];
        for (int num : arr) {
            counts[num % k]++;
        }
        // Count of element with remainder 0
        int zeroCount = counts[0];
        // Check if the count of element with remainder 0 is even
        if (zeroCount % 2 != 0) {
            return false;
        }
        for (int i = 1; i < k / 2; i++) {
            // If counts of two elements with remainder i are not equal, then it is not possible
            if (counts[i] != counts[k - i]) {
                return false;
            }
        }
        return true;
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        List<TreeNode> nodes = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            nodes.add(new TreeNode(i));
        }
        for (int[] edge : edges) {
            TreeNode parent = nodes.get(edge[0]);
            TreeNode child = nodes.get(edge[1]);
            parent.children.add(child);
            child.children.add(parent);
        }

        int ans = dfs(nodes.get(0), hasApple);
        return ans == 0 ? 0 : ans - 2; // Min time + 2 for the return to the starting point
    }

private int dfs(TreeNode node, boolean[] hasApple) {
        int res = 0;
        for (TreeNode child : node.children) {
            int childResult = dfs(child, hasApple);
            if (childResult > 0) { // A child has an apple
                res += childResult + 2; // child time + 2 for the return to the starting point
            } else if (hasApple[child.val]) { // Child node itself has an apple
                res += childResult + 2; // child time + 2 for the return to the starting point
            }
        }
        return res;
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        Map<Integer, List<Integer>> map = new HashMap<>();
        int[] vis = new int[n];

        // Build the graph
        for (int[] e : edges) {
            int a = e[0], b = e[1];
            map.computeIfAbsent(a - 1, key -> new ArrayList<>()).add(b - 1);
            map.computeIfAbsent(b - 1, key -> new ArrayList<>()).add(a - 1);
        }

        // Topological Sort
        int start = 0;
        Stack<Integer> st = new Stack<>();
        boolean[] visited = new boolean[n];
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                start = i;
                dfs(start, map, visited, st);
            }
        }

        // Calculate the time
        return calcTime(st, map, hasApple);
    }

private void dfs(int u, Map<Integer, List<Integer>> map, boolean[] visited, Stack<Integer> st) {
        if (visited[u]) return;
        visited[u] = true;
        st.push(u);
        for (int v : map.getOrDefault(u, new ArrayList<>())) {
            dfs(v, map, visited, st);
        }
    }

private int calcTime(Stack<Integer> st, Map<Integer, List<Integer>> map, boolean[] hasApple) {
        int res = 0;
        while (!st.isEmpty()) {
            int u = st.pop();
            if (st.isEmpty()) return res;
            int v = st.peek();
            if (!hasApple[u]) continue;
            res += 2; // Time to travel from u to v
            if (hasApple[v]) res += 2; // Time to travel from v to u
            if (map.containsKey(v) && map.get(v).contains(u)) continue;
            st.push(v);
        }
        return res + 2;
    }

