public int minTime(int n, int[][] edges, boolean[] hasApple) {
    Map<Integer, Set<Integer>> graph = new HashMap<>();
    for (int[] edge : edges) {
        int u = edge[0], v = edge[1];
        graph.computeIfAbsent(u, k -> new HashSet<>()).add(v);
        graph.computeIfAbsent(v, k -> new HashSet<>()).add(u);
    }

    int[] visited = new int[n];
    int time = 0;
    Deque<Integer> stack = new ArrayDeque<>();
    stack.push(0);
    visited[0] = 1;

    while (!stack.isEmpty()) {
        int node = stack.pop();
        for (int neighbor : graph.getOrDefault(node, new HashSet<>())) {
            if (visited[neighbor] == 1) continue;
            visited[neighbor] = 1;
            time += hasApple[neighbor] ? 2 : 0;
            stack.push(neighbor);
        }
    }

    return time;
}

public String sortString(String s) {
        int[] charCount = new int[26];
        Arrays.fill(charCount, 0);

        // Count occurrences of each character
        for (char c : s.toCharArray()) {
            charCount[c - 'a']++;
        }

        StringBuilder result = new StringBuilder();
        int i = 0;

        // Sort characters Alphabatically
        while (true) {
            for (int j = 0; j < 26; j++) {
                if (charCount[j] > 0) {
                    result.append((char) (j + 'a'));
                    charCount[j]--;
                }
            }
            // Reverse to sort in descending order
            char[] reversed = result.reverse().toString().toCharArray();
            result = new StringBuilder();
            for (char c : reversed) {
                result.append(c);
            }
        }

        return result.toString();
    }

public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    StringBuilder result = new StringBuilder();

    int i = 0, j = chars.length - 1;
    while (true) {
        if (i <= j) {
            result.append(chars[i++]);
        }
        if (i <= j) {
            result.append(chars[j--]);
        }
        if (i > j) {
            break;
        }
    }

    return result.toString();
}

public String sortString(String s) {
    if (s == null || s.length() == 0) {
        return s;
    }

    int[] freq = new int[128]; // Assuming only ASCII characters
    for (char c : s.toCharArray()) {
        freq[c]++;
    }

    StringBuilder result = new StringBuilder();
    int i = 0, j = 255; // Start and end of the frequency array

    while (result.length() < s.length()) {
        // Pick the smallest character
        for (int k = i; k <= j; k++) {
            if (freq[k] > 0) {
                result.append((char)k);
                freq[k]--;
                break;
            }
        }
        i++;

        // Pick the largest character
        for (int k = j; k >= i; k--) {
            if (freq[k] > 0) {
                result.append((char)k);
                freq[k]--;
                break;
            }
        }
        j--;
    }

    return result.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }

    String result = new String();
    int[] count = new int[128]; // Assuming ASCII range
    for (char ch : s.toCharArray()) {
        count[ch]++;
    }

    PriorityQueue<Character> minHeap = new PriorityQueue<>((c1, c2) -> Integer.compare(count[c1], count[c2]));
    for (int i = 0; i < 128; i++) {
        if (count[i] > 0) {
            minHeap.add((char) i);
        }
    }

    PriorityQueue<Character> maxHeap = new PriorityQueue<>((c1, c2) -> Integer.compare(count[c2], count[c1]));
    for (int i = 127; i >= 0; i--) {
        if (count[i] > 0) {
            maxHeap.add((char) i);
        }
    }

    while (!minHeap.isEmpty() || !maxHeap.isEmpty()) {
        if (!minHeap.isEmpty() && !maxHeap.isEmpty()) {
            if (count[minHeap.peek()] != count[maxHeap.peek()]) {
                result += minHeap.poll();
                result += maxHeap.poll();
            } else {
                char remaining = minHeap.isEmpty() ? maxHeap.poll() : minHeap.poll();
                result += remaining;
                count[remaining]--;
                while (!minHeap.isEmpty() && count[minHeap.peek()] == 0) {
                    minHeap.poll();
                }
                while (!maxHeap.isEmpty() && count[maxHeap.peek()] == 0) {
                    maxHeap.poll();
                }
            }
        } else if (!minHeap.isEmpty()) {
            result += minHeap.poll();
            count[minHeap.peek()]--;
            while (!minHeap.isEmpty() && count[minHeap.peek()] == 0) {
                minHeap.poll();
            }
        } else {
            result += maxHeap.poll();
            count[maxHeap.peek()]--;
            while (!maxHeap.isEmpty() && count[maxHeap.peek()] == 0) {
                maxHeap.poll();
            }
        }
    }

    return result;
}

