public boolean splitArraySameAverage(int[] nums) {
    if (nums.length <= 2) return false;

    int total = 0;
    for (int num : nums) total += num;

    if (total * 2 % nums.length != 0) return false;

    int target = total * 2 / nums.length;

    int start = 1;
    int end = nums.length - 2;
    int currentSum = nums[0] + nums[end];

    while (start < end) {
        if (currentSum == target) {
            int presum = 0;
            for (int i = 0; i < nums.length - 2; i++) {
                presum += nums[i];
                if (presum == target) return true;
            }
        }

        if (currentSum < target) {
            currentSum += nums[start];
            start++;
        } else {
            currentSum -= nums[end];
            end--;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = Arrays.stream(nums).sum();
    int n = nums.length;
    if (n <= 1) return false;

    int average = sum / n;

    Map<Integer, Integer> map = new HashMap<>();
    int prefixSum = 0;

    for (int num : nums) {
        prefixSum += num;
        map.put(prefixSum % average, map.getOrDefault(prefixSum % average, 0) + 1);
    }

    map.put(0, 1);  // Key 0 has a value of 1 to handle the case when the split makes up for the middle element

    for (int num : nums) {
        prefixSum -= num;
        if (prefixSum % average == 0 && map.containsKey(prefixSum / average)) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) return false; // Edge case: one element cannot be split

    int sum = Arrays.stream(nums).sum();
    int targetSum = sum / n;
    Set<Integer> set = new HashSet<>();

    for (int i = 0; i < n; i++) {
        int currentSum = sum - nums[i];
        if (i == 0) {
            if (currentSum == targetSum) return true;
            set.add(currentSum);
        } else {
            int previousSum = sum - nums[i];
            if (previousSum == targetSum) return true;
            set.add(currentSum);
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = Arrays.stream(nums).sum();
    if (nums.length % 2 != 0) {
        return false;
    }

    int average = sum / nums.length;
    HashSet<Integer> sumSet = new HashSet<>();

    for (int num : nums) {
        int leftSum = sum - num;
        if (leftSum >= average && sumSet.contains(leftSum)) {
            return true;
        }
        sumSet.add(num);
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    // Calculate the total sum of the array
    int totalSum = Arrays.stream(nums).sum();
    // If the total sum is odd, then it's impossible to split the array with equal average
    if (totalSum % 2 != 0) {
        return false;
    }
    // Try to find a subarray with sum equals to n/2
    for (int n = nums.length / 2; n > 0; n--) {
        if (canFindSubset(nums, n, totalSum / 2)) {
            return true;
        }
    }
    return false;
}

private boolean canFindSubset(int[] nums, int k, int target) {
    if (k == 0) {
        return target == 0;
    }
    int sum = 0;
    for (int i = 0; i < k; i++) {
        sum += nums[i];
    }
    // This problem is equivalent to finding if there exists a subset of length k with sum target
    return sum <= target && canFindSubset(nums, k - 1, target - sum) || canFindSubset(nums, k - 1, target);
}

public int minCostClimbingStairs(int[] cost) {
    int[] dp = new int[cost.length + 1];

    // Base cases: the cost to reach the top from the first or second step is the value of that step
    dp[0] = cost[0];
    dp[1] = cost[1];

    // Fill the dp array
    for (int i = 2; i <= cost.length; i++) {
        // The minimum cost to reach i is the minimum of the cost to reach i-1 or i-2, plus the cost of i
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i - 1];
    }

    // The minimum cost to reach the top is the minimum of the cost to reach the second last or last step
    return Math.min(dp[cost.length - 1], dp[cost.length]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        throw new IllegalArgumentException("Cost array must not be null or empty");
    }
    int length = cost.length;
    if (length <= 2) {
        return Arrays.stream(cost).min().getAsInt();
    }

    int[] dp = new int[length];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < length; i++) {
        dp[i] = cost[i] + Math.min(dp[i-1], dp[i-2]);
    }

    return Math.min(dp[length-1], dp[length-2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }

    // Initialize the cost array to store the minimum cost of reaching each step
    int[] minCost = new int[cost.length];
    minCost[0] = cost[0];
    minCost[1] = cost[1];

    for (int i = 2; i < cost.length; i++) {
        // Calculate the minimum cost of reaching the current step by considering the two possible ways to reach it
        minCost[i] = Math.min(minCost[i - 1], minCost[i - 2]) + cost[i];
    }

    // The minimum cost to reach the top of the floor is the minimum of the last two steps
    return Math.min(minCost[minCost.length - 1], minCost[minCost.length - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0 || n == 1) {
        return cost[0];
    }

    int[] dp = new int[n + 1];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i - 1];
    }

    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        throw new IllegalArgumentException("Input array cannot be null or empty");
    }

    int[] minCost = new int[cost.length];
    minCost[0] = cost[0];
    minCost[1] = cost[1];

    for (int i = 2; i < cost.length; i++) {
        minCost[i] = Math.min(minCost[i - 1], minCost[i - 2]) + cost[i];
    }

    return Math.min(minCost[cost.length - 1], minCost[cost.length - 2]);
}

