public boolean hasAllCodes(String s, int k) {
    Set<String> countdown = new HashSet<>();
    for (int start = 0; start < s.length() - k + 1; start++) {
        countdown.add(s.substring(start, start + k));
        if (countdown.size() == (int) Math.pow(2, k)) {
            return true;
        }
    }
    return false;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k || k < 1) {
        return false;
    }
    boolean[] visited = new boolean[1 << k];
    String window = s.substring(0, k);
    visited[Integer.parseInt(window, 2)] = true;

    for (int i = k; i < s.length(); i++) {
        window = window.substring(1) + s.charAt(i);
        int word = Integer.parseInt(window, 2);
        if (visited[word]) {
            return false;
        }
        visited[word] = true;
    }

    return true;
}

public boolean hasAllCodes(String s, int k) {
    int length = s.length(), need = (1 << k) - 1;
    if (length < k) return false;

    Set<Integer> bits = new HashSet<>();
    int all = 0;

    for (int i = 0; i < length - k + 1; i++) {
        all |= (1 << k - 1) ^ (Integer.parseInt(s.substring(i, i + k), 2));
        if (bits.contains(all)) return false;
        bits.add(all);
    }

    return bits.contains(0);
}

public static boolean hasAllCodes(String s, int k) {
        HashSet<String> set = new HashSet<>();
        int windowStart = 0;

        for (int windowEnd = 0; windowEnd < s.length(); windowEnd++) {
            String substring = s.substring(windowStart, windowEnd + 1);
            if (set.contains(substring)) { // Check if the substring is already present in the set
                return false;
            } else { // Add the substring to the set
                set.add(substring);

                // If the current window length equals k, move the window start to the right
                if (windowEnd - windowStart + 1 == k) {
                    windowStart++; // Increment the window start
                }
            }
        }

        // If the length of the set is equal to the possible number of k-length binary strings, return true
        return set.size() == 1 << k;
    }

public boolean hasAllCodes(String s, int k) {
    Set<String> seen = new HashSet<>();

    // Loop through the string to find all substrings of length k
    for (int i = 0; i <= s.length() - k; i++) {
        String substring = s.substring(i, i + k);

        // If the substring is already in the set, return false (it's redundant)
        if (seen.contains(substring)) {
            return false;
        }

        // Add the substring to the set of seen substrings
        seen.add(substring);
    }

    // If all substrings were found, return true
    return true;
}

