        if (low > high) {
            throw new IllegalArgumentException("Low boundary cannot be greater than high boundary.");
        }

        List<Integer> steppingNumbers = new ArrayList<>();
        for (int i = low; i <= high; i++) {
            if (isSteppingNumber(i)) {
                steppingNumbers.add(i);
            }
        }

        return steppingNumbers;
    }

private static boolean isSteppingNumber(int number) {
        int previousDigit = -1;
        while (number > 0) {
            int currentDigit = number % 10;
            if (previousDigit == -1 || (previousDigit == currentDigit - 1 || previousDigit == currentDigit + 1)) {
                previousDigit = currentDigit;
                number /= 10;
            } else {
                return false;
            }
        }
        return true;
    }

