private static boolean isSteppingNumber(int num) {
    if (num < 10) {
        return true;
    }
    int prevDigit = -1;
    while (num > 0) {
        int currDigit = num % 10;
        if ((currDigit - prevDigit == 1 || currDigit - prevDigit == -1) && (prevDigit != -1)) {
            prevDigit = currDigit;
        } else {
            return false;
        }
        num /= 10;
    }
    return true;
}

