        count += countOfOnesInNumber(i);
    }

    return count;
}

private static int countOfOnesInNumber(int number) {
    int count = 0;
    int divisor = 1;

    while (number > 0) {
        int digit = number % 10;
        if (digit == 1) {
            count += number - divisor - (number / (divisor * 10)) * divisor + 1;
        }
        count += countOfOnesInNumber(number / 10);
        divisor *= 10;
    }

    return count;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }

    int result = 0;
    int power = 1;
    while (n >= power) {
        int placeValue = n / power;
        int lastDigit = n % power;

        int digitCount = (lastDigit + 1) / 1;
        if (lastDigit % 10 == 1) {
            digitCount++;
        }

        result += digitCount * power;

        if (placeValue > 1) {
            result += placeValue * power;
        }

        if (lastDigit == 0) {
            break;
        }

        power *= 10;
    }

    return result;
}

