            if (mat[i][j] == 1) {
                dp[i][j] = 1;
                // Horizontal
                if (j > 0 && mat[i][j - 1] == 1) {
                    dp[i][j] = Math.max(dp[i][j], dp[i][j - 1] + 1);
                }
                // Vertical
                if (i > 0 && mat[i - 1][j] == 1) {
                    dp[i][j] = Math.max(dp[i][j], dp[i - 1][j] + 1);
                }
                // Diagonal
                if (i > 0 && j > 0 && mat[i - 1][j - 1] == 1) {
                    dp[i][j] = Math.max(dp[i][j], dp[i - 1][j - 1] + 1);
                }
                // Anti-diagonal
                if (i > 0 && j < mat[0].length - 1 && mat[i - 1][j + 1] == 1) {
                    dp[i][j] = Math.max(dp[i][j], dp[i - 1][j + 1] + 1);
                }

                maxLength = Math.max(maxLength, dp[i][j]);
            }
        }
    }

    return maxLength;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int row = mat.length;
    int col = mat[0].length;
    int maxLength = 0;

    // Mask for horizontal checking
    int horizontalMask = 1 << (col - 1);
    // Mask for vertical checking
    int verticalMask = 1;

    for (int i = 0; i < row; i++) {
        int currentHorizontalLength = 0;
        int currentVerticalLength = 0;

        for (int j = 0; j < col; j++) {
            int currentCellMask = 1 << j;

            if ((mat[i][j] & currentCellMask) != 0) {
                currentHorizontalLength++;
                currentVerticalLength++;
            } else {
                currentHorizontalLength = 0;
                currentVerticalLength = 1;
            }

            if ((mat[i][j] & horizontalMask) != 0 && currentHorizontalLength > maxLength) {
                maxLength = currentHorizontalLength;
            }

            if ((mat[i][j] & verticalMask) != 0 && currentVerticalLength > maxLength) {
                maxLength = currentVerticalLength;
            }
        }
    }

    return maxLength;
}

