    String numStr = Integer.toString(n);
    // Reverse the string to facilitate insertion of separators
    StringBuilder sb = new StringBuilder(numStr).reverse();
    // Insert a dot every thousand digits
    for (int i = 3; i <= sb.length(); i += 3) {
