    }

    String result = "";
    StringBuilder buffer = new StringBuilder();

    // Extract each group of three digits
    while (n > 0) {
        int remainder = n % 1000;
        if (remainder > 0) {
            buffer.insert(0, remainder);
            if (buffer.length() > 3) {
                buffer.insert(3, '.');
            }
        }
        n /= 1000;
    }

    if (buffer.length() > 0 && !buffer.charAt(0).equals('.')) {
        result += buffer.toString().substring(1);
    }

    return result;
}

