public static int squarePermutations(int[] A) {
        Set<int[]> perm = new HashSet<>();
        if (A.length < 2) {
            perm.add(new int[]{A[0]});
            return perm.size();
        }
        backtrack(0, A, new boolean[A.length], perm);
        return perm.size();
    }

private static void backtrack(int start, int[] A, boolean[] used, Set<int[]> perm) {
        if (start == A.length) {
            perm.add(new intA.Clone());
            return;
        }
        for (int i = start; i < A.length; i++) {
            if (used[i] || (i > start && !used[i - 1] && A[i] == A[i - 1])) {
                continue;
            }
            used[i] = true;
            backtrack(start + 1, A, used, perm);
            used[i] = false;
        }
    }

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    // Sort the array
    Arrays.sort(A);

    // Initialize a counter for valid permutations
    long count = 0;

    // Helper function to check if a number is a perfect square
    boolean isPerfectSquare = (long) A[A.length - 1] * A[A.length - 1] == A[A.length - 2] * A[A.length - 2];

    int start = 0;

    while (start < A.length - 1) {
        if (isPerfectSquare) {
            if (A[start] == A[start + 1]) {
                count++;
            }
            int j = i + 1;
            while (j < A.length - 1 && A[j] == A[j + 1]) {
                j++;
            }
            count += (j - i - 2) * count;
            start = j;
        } else {
            break;
        }
    }

    return (int) (count);
}

public static int squarePermutations(int[] A) {
