            if (A[i] * A[i] != A[i - 1] * A[i - 1]) {
                continue;
            }

            int current = count[i - 1];

            for (int j = i - 2; j >= 0; j--) {
                if (A[i] * A[i] == A[j] * A[j]) {
                    count[j] += current;
                }
            }

            options *= current;
        }

        int result = 0;
