    }

public static int squarePermutations(int[] A) {
        if (A == null || A.length == 0) {
            return 0;
        }
        int n = A.length;
        Map<Integer, Integer> squareMap = new HashMap<>();
        for (int i = 0; i < n; i++) {
            squareMap.put(A[i], squareMap.getOrDefault(A[i], 0) + 1);
        }

        if (!isSumSquare(A)) {
            return 0;
        }

        int uniquePerm = 1;
        for (int.freq : squareMap.values()) {
            uniquePerm *= factorial(freq);
        }

        return factorial(n) / uniquePerm;
    }

private static boolean isSumSquare(int[] A) {
        for (int i = 0; i < A.length - 1; i++) {
            int sum = A[i] + A[i + 1];
            if (Math.sqrt(sum) != Math.floor(Math.sqrt(sum))) {
                return false;
            }
        }
        return true;
    }

private static int factorial(int n) {
        if (n == 0) {
            return 1;
        }
        int result = 1;
        for (int i = 2; i <= n; i++) {
            result *= i;
        }
        return result;
    }

public static int squarePermutations(int[] A) {
        if (A == null || A.length == 0) {
            throw new IllegalArgumentException("Input array cannot be null or empty");
        }

        int len = A.length;
        int maxElement = 0;
        for (int num : A) maxElement = Math.max(maxElement, num);

        // Check if all elements are perfect squares
        for (int num : A) {
            if (!isPerfectSquare(num)) {
                return 0;
            }
        }

        // Generate permutations
        BigInteger count = generatePermutations(A, maxElement, new boolean[A.length], 0, new BigInteger[]{}).add(BigInteger.ONE).subtract(BigInteger.ONE);
        return count.intValueExact();
    }

private static boolean isPerfectSquare(int num) {
        int sqrt = (int) Math.sqrt(num);
        return sqrt * sqrt == num;
    }

private static BigInteger generatePermutations(int[] A, int maxElement, boolean[] used, int currentLen, BigInteger[] permutations) {
        if (currentLen == A.length) {
            return combine(permutations);
        }

        for (int i = 0; i < A.length; i++) {
            if (used[i]) continue;

            if (currentLen > 0 && A[i] <= permutations[currentLen - 1] || Math.abs(A[i] - permutations[currentLen - 1]) > 1) {
                used[i] = true;
                permutations[currentLen] = BigInteger.valueOf(A[i]);
                BigInteger nextPermutations = generatePermutations(A, maxElement, used, currentLen + 1, permutations);
                used[i] = false;
                permutations[currentLen] = BigInteger.ZERO;
                nextPermutations.add(BigInteger.ONE);
            }
        }
        return new BigInteger("0");
    }

private static BigInteger combine(BigInteger[] permutations) {
        BigInteger result = BigInteger.ONE;
        for (BigInteger num : permutations) result = result.multiply(num);
        return result;
    }

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int left[] = new int[n];
    int right[] = new int[n];
    int result = 0;

    // Find the left boundary of each bar
    left[0] = -1;
    for (int i = 1; i < n; i++) {
        while (i > 0 && heights[i] <= heights[i - 1]) {
            i = left[i - 1];
        }
        left[i] = (i > 0) ? i - 1 : -1;
    }

    // Find the right boundary of each bar
    right[n - 1] = n;
    for (int i = n - 2; i >= 0; i--) {
        while (i < n - 1 && heights[i] <= heights[i + 1]) {
            i = right[i + 1];
        }
        right[i] = (i < n - 1) ? i + 1 : n;
    }

    // Calculate the area of each bar and find the maximum area
    for (int i = 0; i < n; i++) {
        result = Math.max(result, heights[i] * (right[i] - left[i] - 1));
    }

    return result;
}

public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    Stack<Integer> stack = new Stack<>();

    for (int i = 0; i < heights.length || !stack.isEmpty(); i++) {
        int height = (i == heights.length) ? 0 : heights[i];

        while (!stack.isEmpty() && heights[stack.peek()] >= height) {
            int poppedIndex = stack.pop();
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            maxArea = Math.max(maxArea, heights[poppedIndex] * width);
        }

        stack.push(i);
    }

    return maxArea;
}

