        while (!stack.isEmpty() && heights[i] < heights[stack.peek()]) {
            int currentHeight = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            maxArea = Math.max(maxArea, currentHeight * width);
        }
        stack.push(i);
    }

    while (!stack.isEmpty()) {
        int currentHeight = heights[stack.pop()];
