    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        throw new IllegalArgumentException("Input matrix cannot be null or empty");
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int index = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            result[index++] = mat[i][j];
        }
        for (int j = 1; j < rows - i && j < cols; j++) {
            result[index++] = mat[i + j][j];
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }

    int N = mat.length, M = mat[0].length;
    int[] result = new int[N * M];
    int leftTop = 0, rightBottom = M - 1;
    int index = 0;

    while (index < N * M) {
        for (int i = leftTop; i <= rightBottom && index < N * M; i++) {
            result[index++] = mat[leftTop][i];
        }
        leftTop++;

        for (int i = rightBottom; i >= leftTop && index < N * M; i--) {
            result[index++] = mat[i][rightBottom];
        }
        rightBottom--;
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }

    int rows = mat.length, cols = mat[0].length;
    int[] result = new int[rows * cols];
    int idx = 0;

    // Traverse from the top-left corner
    for (int layer = 0; layer < Math.max(rows, cols); layer++) {
        int startRow = Math.max(0, layer);
        int startCol = Math.max(0, layer);
        int endRow = Math.min(rows - 1, startRow + layer);
        int endCol = Math.min(cols - 1, startCol + layer);

        for (int i = startRow, j = startCol; i <= endRow && j <= endCol; i++, j++) {
            result[idx++] = mat[i][j];
        }
    }

    // Traverse from the bottom-right corner to the top-left corner in reverse
    for (int layer = Math.max(rows, cols) - 2; layer >= 0; layer--) {
        int startRow = Math.max(0, layer);
        int startCol = Math.max(0, layer);
        int endRow = Math.min(rows - 1, startRow + layer);
        int endCol = Math.min(cols - 1, startCol + layer);

        for (int i = endRow, j = endCol; i >= startRow && j >= startCol; i--, j--) {
            result[idx++] = mat[i][j];
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        throw new IllegalArgumentException("Input matrix is null or empty");
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int index = 0;

    for (int row = 0; row < rows; row++) {
        if (row == 0) {
            // First row
            for (int col = 0; col < cols; col++) {
                result[index++] = mat[row][col];
            }
        } else if (row == rows - 1) {
            // Last row
            for (int col = cols - 1; col >= 0; col--) {
                result[index++] = mat[row][col];
            }
        } else {
            // Middle rows
            for (int col = 0; col < cols; col++) {
                if (col % 2 == 0) {
                    result[index++] = mat[row][col];
                } else {
                    result[index++] = mat[row][cols - 1 - col];
                }
            }
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int numRows = mat.length;
    int numCols = mat[0].length;
    int[] result = new int[numRows * numCols];
    boolean add = true; // true for down, false for up

    for (int index = 0, row = 0, col = 0; index < result.length; index++) {
        result[index] = mat[row][col];
        if (add) {
            if (col + 1 < numCols) {
                col++;
            } else if (row + 1 < numRows) {
                row++;
            } else {
                add = false;
                numCols--;
                row += 1;
                col = numCols - 1;
            }
        } else {
            if (row + 1 < numRows) {
                row++;
            } else if (col - 1 >= 0) {
                col--;
            } else {
                add = true;
                numRows--;
                row = numRows - 1;
                col = 0;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
