    for (int i = 0; i < str.length() - 1; i++) {
        char current = str.charAt(i);
        if (Character.digit(current, 10) > Character.digit(str.charAt(i + 1), 10)) {
            // Create a new string by swapping the first digit with the smallest one longer
            StringBuilder newStr = new StringBuilder(str.substring(i) + str.charAt(i) + str.substring(i + 1));
            try {
                // Convert the string back to an integer and check if it's greater than n
