                if (result > n) return result;
            } catch (NumberFormatException e) {
                // Handle case where the resulting number is not a valid integer
                // For example, this can happen if the constructed number is not a valid number (like '111')
            }
        }
    }
    return -1; // No valid smaller number found
}

public static int findSmallestInteger(int n) {
    if (n <= 10) return -1; // The smallest number greater than 10 is 11.

    int[] digits = Integer.toString(n).chars()
                                                 .map(c -> c - '0')
                                                 .toArray();

    for (int i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            for (int j = digits.length - 1; j > i; j--) {
                if (digits[j] > digits[i]) {
                    // Swap the digits
                    int temp = digits[i];
                    digits[i] = digits[j];
                    digits[j] = temp;

                    // Sort the remaining digits in ascending order
                    Arrays.sort(digits, i + 1, digits.length);
                    StringBuilder sb = new StringBuilder();
                    for (int digit : digits) {
                        sb.append(digit);
                    }
                    return Integer.parseInt(sb.toString());
                }
            }
        }
    }

    // If no such number can be formed, return -1
    return -1;
}

public static int findSmallestInteger(int n) {
    // Check if n itself is > 0 and not 1
    if (n <= 0 || n == 1) {
        return -1;
    }

    // Convert the integer to a character array for easy manipulation
    char[] digits = String.valueOf(n).toCharArray();
    int length = digits.length;

    // Find the first digit from the right that is not in descending order
    for (int i = length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            // Find the smallest digit in the right part that is larger than digits[i]
            int j = length - 1;
            while (digits[j] <= digits[i]) {
                j--;
            }

            // Swap digits[i] and digits[j]
            char temp = digits[i];
            digits[i] = digits[j];
            digits[j] = temp;

            // Sort the right part of the array
            Arrays.sort(digits, i + 1, length);

            // Convert the modified array back to an integer
            return Integer.parseInt(new String(digits));
        }
    }

    // If no such digit is found, the number is already in ascending order and cannot be rearranged
    return -1;
}

public static int findSmallestInteger(int n) {
    if (n <= 9) {
        return n; // Single digit numbers are inherently the smallest.
    }

    Stack<Character> digitsStack = new Stack<>();
    while (n > 0) {
        digitsStack.push((char) (n % 10 + '0'));
        n /= 10;
    }

    boolean found = false;
    while (!found) {
        Stack<Character> tempStack = new Stack<>(digitsStack);
        char temp; // To hold character while peeking
        char prevMax = '9'; // Previous максималь digit

        while (!tempStack.isEmpty()) {
            temp = tempStack.pop();
            prevMax = Math.min(prevMax, temp);

            if (temp != prevMax) {
                found = true;
                break;
            }
        }

        if (found) {
            // Make a modification by replacing the previous max digit with the smallest next digit.
            for (char i = '0'; i <= prevMax; i++) {
                if (tempStack.contains(i) && Character.compare(temp, i) < 0) {
                    temp = i;
                    break;
                }
            }

            // Swap the found maximum with the smallest next digit.
            int i = tempStack.search((char) (temp + '0'));
            tempStack.set(i, temp);
            tempStack.set((i - 1 < 0) ? tempStack.size() - 1 : i - 1, prevMax);

            // Convert the stack back to an integer.
            int result = 0;
            while (!tempStack.isEmpty()) {
                result = result * 10 + tempStack.pop() - '0';
            }
            return result;
        } else {
            return -1; // No larger permutation possible.
        }
    }
}

public static int findSmallestInteger(int n) {
    // Convert the number to a string to easily access the digits
    String numStr = Integer.toString(n);

    // Check for the case where n is already the smallest possible permutation
    if (isSmallestPermutation(numStr)) {
        return -1;
    }

    // Find the smallest digit to swap
    char smallestDigit = findSmallestDigit(numStr);

    // Find the position of the smallest digit
    int smallestDigitIndex = numStr.indexOf(smallestDigit);

    // Create a new string by swapping the smallest digit with the first digit to the right of it
    String result = swapDigits(numStr, smallestDigitIndex, 0);

    // Convert the result back to an integer and return
    int resultInt = Integer.parseInt(result);
    return resultInt;
}

private static boolean isSmallestPermutation(String num) {
    // Sort the string to check if it's a permutation of sorted digits
    String sortedNum = num.chars()
                                .sorted()
                                .mapToObj(c -> String.valueOf(c))
                                .collect(Collectors.joining());
    return sortedNum.equals(num);
}

private static char findSmallestDigit(String num) {
    for (char digit : num.toCharArray()) {
        if (digit > '0') {
            return digit;
        }
    }
    return '9'; // If all digits are '0', smallest digit is '9'
}

private static String swapDigits(String num, int i, int j) {
    char[] chars = num.toCharArray();
    char temp = chars[i];
    chars[i] = chars[j];
    chars[j] = temp;
    return new String(chars);
}

public static List<String> centerSymmetricNumbers(int n) {
