public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n % 2 == 0) {
        return result; // No symmetric numbers of even length
    }

    String possiblePrefix = "9";
    while (possiblePrefix.length() <= n) {
        String prefix = possiblePrefix;
        String reversedPrefix = new StringBuilder(prefix).reverse().toString();
        String oddSuffix = doNumberLookUp("0" + reversedPrefix + "0", n + 1);
        result.add(prefix + oddSuffix + prefix);
        possiblePrefix += "9" + "8";
    }

    return result;
}

private static String doNumberLookUp(String num, int length) {
    if (length == num.length()) {
        return num;
    }
    int nextNum = Integer.parseInt(num.substring(num.length() - 1)) + 1;
    return doNumberLookUp(String.valueOf(nextNum), length);
}

