public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length < 3 || points[0].length != 2 || points[1].length != 2 || points[2].length != 2) {
        throw new IllegalArgumentException("Invalid input");
    }

    if (
        points[0][0] == points[1][0] && points[0][1] == points[1][1]
        || points[0][0] == points[2][0] && points[0][1] == points[2][1]
        || points[1][0] == points[2][0] && points[1][1] == points[2][1]
    ) {
        return false;
    }

    // Calculate the slopes of the sides
    double slope1 = calculateSlope(points[0], points[1]);
    double slope2 = calculateSlope(points[1], points[2]);

    // Check if the slopes are not equal, forming a triangle
    return slope1 != slope2;
}

private double calculateSlope(int[] point1, int[] point2) {
    return (point2[1] - point1[1]) / (point2[0] - point1[0]);
}

public static boolean isBoomerang(int[][] points) {
