    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    // Check if the points form a straight line
    if ((x1 - x2) * (y2 - y3) == (x2 - x3) * (y3 - y1)) {
        return false;
    }

    return true;
}

