public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        throw new IllegalArgumentException("Input string cannot be null or empty");
    }

    int maxEnergy = 0;
    int currentEnergy = 1;
    char previousChar = s.charAt(0);

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == previousChar) {
            currentEnergy++;
        } else {
            previousChar = s.charAt(i);
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 1;
        }
    }

    maxEnergy = Math.max(maxEnergy, currentEnergy); // Handle the last group of characters

    return maxEnergy;
}

