public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        node(n, i, result);
    }
    Collections.sort(result);
    return result;
}

private static void node(int n, int val, List<Integer> result) {
    if (val > n) return;
    result.add(val);
    for (int i = 0; i <= 9; i++) {
        node(n, 10 * val + i, result);
    }
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }

    dfs(result, 0, n);
    return result;
}

private static void dfs(List<Integer> result, int current, int n) {
    if (current >= n) {
        return;
    }
    result.add(current);

    for (int digit = 0; digit <= 9; digit++) {
        if (current == 0 && digit == 0) {
            continue; // Skip leading zeros in the first part
        }
        int nextValue = current * 10 + digit;
        if (nextValue <= n) {
            dfs(result, nextValue, n);
        }
    }
}

public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        if (n == 0) return result;

        int current = 1;
        for (int i = 1; i <= n; i++) {
            result.add(current);
            if (current * 10 <= n) {
                current *= 10;
            } else {
                while (current % 10 != 9) {
                    current--;
                }
                current /= 10;
            }
        }
        return result;
    }

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new LinkedList<>();
    if (n < 1) return result;

    // Create a root node with value 1
    IntervalTreeNode root = new IntervalTreeNode(1);

    // Construct the interval tree to allow lexicographical order
    for (int i = 2; i <= n; i++) {
        int digit = i % 10;
        IntervalTreeNode parent = root;
        IntervalTreeNode current = parent.left;

        // Traverse the tree to find the correct position
        while (current != null && current.value < digit) {
            parent = current;
            current = current.right;
        }

        // Insert the new node into the correct position
        if (current == null) {
            parent.right = new IntervalTreeNode(digit);
        } else {
            current.value = digit;
        }
    }

    // Collect elements from the interval tree into the result list
    collectNodes(root.left, result);

    return result;
}

public IntervalTreeNode(int val) {
        this.value = val;
        this.left = null;
        this.right = null;
    }

void collectNodes(IntervalTreeNode node, List<Integer> result) {
    if (node == null) return;

    collectNodes(node.left, result);
    result.add(node.value);
    collectNodes(node.right, result);
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> list = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        helper(i, n, list);
    }
    return list;
}

private static void helper(int num, int n, List<Integer> list) {
    if (num <= n) {
        list.add(num);
    }
    for (int i = 0; i <= 9; i++) {
        int nextNum = num * 10 + i;
        if (nextNum <= n) {
            helper(nextNum, n, list);
        }
    }
}

