public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }

    boolean[] isUnique = new boolean[nums.length];
    int uniqueSum = 0;

    for (int i = 0; i < nums.length; i++) {
        if (isUnique[i]) {
            continue;
        }
        isUnique[i] = true;
        for (int j = i + 1; j < nums.length; j++) {
            if (nums[i] == nums[j]) {
                isUnique[j] = false;
                break;
            }
        }
        if (isUnique[i]) {
            uniqueSum += nums[i];
        }
    }

    return uniqueSum;
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);

    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("Input must be a positive integer.");
        }

        Set<Integer> set = new HashSet<>();
        set.add(0);

        for (int i = 1; i <= Math.sqrt(n); i++) {
            int num = i * i;
            for (int j : set) {
                int sum = j + num;
                if (sum == n) {
                    return i;
                } else if (sum < n) {
                    set.add(sum);
                }
            }
        }

        return n; // This line will not be reached for proper input validation.
    }

